import data from './data/srd-creatures.json';
import pf2eRows from './data/pf2e-creatures.json';
import { CreatureTemplate } from './types';

/**
 * Monsters and NPCs from the D&D 5e System Reference Document 5.1 (CC-BY-4.0, see NOTICE.md).
 * Generated by scripts/build-creatures.mjs.
 */
export const srdCreatures: CreatureTemplate[] = (data as CreatureTemplate[]).map((c) => ({
  ...c,
  ruleset: '5e',
}));

/** The id of a Pathfinder creature, made from its name (names are unique in the list). */
export const pf2eId = (name: string) =>
  'pf2e-' +
  name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

/**
 * Creatures from Pathfinder Monster Core and Monster Core 2 (Paizo, ORC License, see NOTICE.md),
 * stored as compact rows [name, AC, HP, Perception, level] by scripts/build-pf2e-creatures.mjs.
 * Pathfinder rolls initiative with Perception, so that is the initiative bonus.
 */
export const pf2eCreatures: CreatureTemplate[] = (
  pf2eRows as [string, number, number, number, number][]
).map(([name, ac, hp, perception, level]) => ({
  id: pf2eId(name),
  name,
  ac,
  hp,
  initiativeBonus: perception,
  level,
  ruleset: 'PF2e',
}));

/** The built-in list: the SRD creatures first, then the Pathfinder ones. */
export const defaultCreatures: CreatureTemplate[] = srdCreatures.concat(pf2eCreatures);

export function initiativeBonusFromDex(dex: number): number {
  return Math.floor((dex - 10) / 2);
}

export function creatureBonus(c: CreatureTemplate): number {
  if (typeof c.initiativeBonus === 'number') return c.initiativeBonus;
  return typeof c.dex === 'number' ? initiativeBonusFromDex(c.dex) : 0;
}

/** Names starting with the text come first, then names that contain it. Case-insensitive. */
export function searchCreatures(
  list: CreatureTemplate[],
  query: string,
  limit = 8,
): CreatureTemplate[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const starts: CreatureTemplate[] = [];
  const contains: CreatureTemplate[] = [];
  for (const c of list) {
    const name = c.name.toLowerCase();
    if (name.startsWith(q)) starts.push(c);
    else if (name.includes(q)) contains.push(c);
  }
  return starts.concat(contains).slice(0, limit);
}
